namespace CSharpPracticum.Tasks.Level2;
internal class Student(string name,double averageGrade):IComparable<Student>{public string Name{get;}=name;public double AverageGrade{get;}=averageGrade;public int CompareTo(Student? other)=>other is null?1:other.AverageGrade.CompareTo(AverageGrade);public override string ToString()=>$"{Name}: {AverageGrade}";}internal class ByNameComparer:IComparer<Student>{public int Compare(Student? a,Student? b)=>string.Compare(a?.Name,b?.Name,StringComparison.CurrentCulture);}
internal class Task27_Student:ITask{public string Title=>"Задание 27: IComparable/IComparer для Student";public string Description=>"Сортировать студентов по оценке и по имени.";public string[] Requirements=>new[]{"Student: Name и AverageGrade.","IComparable сортирует по оценке по убыванию.","ByNameComparer сортирует по имени.","Показать оба порядка."};public void Run(){List<Student>s=new(){new("Иван",4.2),new("Анна",4.8),new("Борис",3.9)};s.Sort();Console.WriteLine(string.Join("; ",s));s.Sort(new ByNameComparer());Console.WriteLine(string.Join("; ",s));}}
